'use client'
import { useState, type CSSProperties } from 'react'
import { type DayPoint, compactNumber, formatDay, formatNumber, niceTicks } from '@/hooks/useChart'
import { cn } from '@/lib/cn'

// A red bar per day (BarChart.vue). The axis starts at 0 and ends on a round number in four steps; grid lines are 1px
// hairlines. A day with any activity keeps a visible bar. Pointing at a bar names its day and value in the caption and
// quiets the others. The bars rise from the axis once, staggered over the same 120ms for 7 days or 90.
// `focus`: bars lit from outside, the rest quiet, as under the pointer; `note`: what the caption says meanwhile.
// `week`: the change over the last seven days, set over those bars. `held`: on its way, the axis alone at its height.
// `bare` drops the caption's label, for a chart under a stat that already names it.
export interface BarChartProps {
  points: DayPoint[]
  label: string
  height?: number
  focus?: number[]
  note?: string
  week?: string
  held?: boolean
  bare?: boolean
}

export function BarChart({ points, label, height = 160, focus, note, week, held, bare }: BarChartProps) {
  const ticks = niceTicks(points.map(p => p.value))
  const top = ticks[ticks.length - 1]!
  // Four dates under the bars: the first, the last and two between.
  const n = points.length
  const marks = n ? [...new Set([0, Math.round((n - 1) / 3), Math.round((2 * (n - 1)) / 3), n - 1])].map(i => ({ left: `${((i + 0.5) / n) * 100}%`, text: formatDay(points[i]!.day) })) : []
  const [hover, setHover] = useState<number | null>(null)
  const shown = hover === null ? null : points[hover] ?? null
  const peak = formatNumber(Math.max(0, ...points.map(p => p.value)))
  return (
    <figure data-ds="bar-chart" className="ds-barchart flex flex-col gap-3" data-bare={bare || undefined}>
      <style href="ds-bar-chart" precedence="ds">{css}</style>
      <figcaption className="ds-barchart-cap flex h-5 items-baseline justify-between gap-4">
        <span className="ds-chart-caption">{label}</span>
        {shown
          ? <span className="ds-chart-meta">{`${formatDay(shown.day, true)} `}<span className="font-medium text-fg">{formatNumber(shown.value)}</span></span>
          : note ? <span className="ds-chart-meta">{note}</span> : null}
      </figcaption>
      {held
        ? (
            <div className="grid grid-cols-[40px_minmax(0,1fr)] gap-x-2" aria-hidden="true">
              <div />
              <div className="relative" style={{ height: `${height}px` }}><div className="absolute inset-x-0 bottom-0 border-t border-edge" /></div>
              <div />
              <div className="mt-2 h-4" />
            </div>
          )
        : !points.length
            ? <p className="flex items-center justify-center type-ui text-fg-muted" style={{ height: `${height}px` }}>No activity yet.</p>
            : (
                <div className="grid grid-cols-[40px_minmax(0,1fr)] gap-x-2">
                  <div className="relative" style={{ height: `${height}px` }} aria-hidden="true">
                    {ticks.map(t => <span key={t} className="ds-chart-meta absolute right-0 -translate-y-1/2" style={{ top: `${(1 - t / top) * 100}%` }}>{compactNumber(t)}</span>)}
                  </div>
                  <div
                    className="relative"
                    style={{ height: `${height}px` }}
                    role="img"
                    aria-label={`${label}: ${points.length} days, peak ${peak}${week ? `, ${week} this week` : ''}`}
                    onPointerLeave={() => setHover(null)}
                  >
                    {ticks.map(t => <div key={t} className="pointer-events-none absolute inset-x-0 border-t border-data-grid" style={{ top: `${(1 - t / top) * 100}%` }} />)}
                    {week && !shown && <p className="ds-chart-week" style={{ width: `${(Math.min(7, points.length) / points.length) * 100}%` }}><span className="font-medium tabular-nums">{week}</span><span className="text-fg-muted">this week</span></p>}
                    <div className="absolute inset-0 flex items-end">
                      {points.map((p, i) => (
                        <div key={p.day} className="flex h-full flex-1 items-end" onPointerEnter={() => setHover(i)}>
                          <div
                            className={cn('ds-bar mx-auto w-[70%]', hover === i || (hover === null && (!focus || focus.includes(i))) ? 'bg-data-highlight' : 'bg-ds-neutral-600')}
                            style={{ height: p.value > 0 ? `max(2px, ${(p.value / top) * 100}%)` : '0', '--i': (i * 30) / points.length } as CSSProperties}
                          />
                        </div>
                      ))}
                    </div>
                  </div>
                  <div />
                  <div className="relative mt-2 h-4" aria-hidden="true">
                    {marks.map((m, i) => (
                      <span
                        key={m.text}
                        className={cn('ds-chart-meta absolute whitespace-nowrap', i === 0 ? 'left-0' : i === marks.length - 1 ? 'right-0' : '-translate-x-1/2')}
                        style={i === 0 || i === marks.length - 1 ? {} : { left: m.left }}
                      >{m.text}</span>
                    ))}
                  </div>
                </div>
              )}
    </figure>
  )
}

export default BarChart

const css = `
/* The charts' caption: 12px medium, muted (written in sentence case); meta and axis labels 12px muted in tabular figures. */
.ds-chart-caption { color: var(--ds-color-fg-muted); font-size: var(--ds-text-meta); font-weight: var(--ds-font-weight-medium); line-height: var(--ds-text-meta-leading); }
.ds-chart-meta { color: var(--ds-color-fg-muted); font-size: var(--ds-text-meta); line-height: var(--ds-text-meta-leading); font-variant-numeric: tabular-nums; }
/* A bar rises from the axis once (console2.css .c-bar), then only its colour changes. */
.ds-bar { transform-origin: bottom; animation: ds-bar-in var(--ds-duration-rise) var(--ds-easing-out) both; animation-delay: calc(var(--i, 0) * 4ms); transition: background-color var(--ds-duration-glide) var(--ds-easing-standard); }
@keyframes ds-bar-in { from { transform: scaleY(0.02); } }
/* The week's change, over the last seven bars on a red rule. */
.ds-chart-week { position: absolute; right: 0; bottom: 100%; display: flex; justify-content: flex-end; gap: var(--ds-space-xs); margin-bottom: var(--ds-space-xs); padding-bottom: calc(var(--ds-space-xs) - 1px); border-bottom: var(--ds-border-hairline) solid var(--ds-color-edge-accent); font-size: var(--ds-text-meta); line-height: var(--ds-text-meta-leading); white-space: nowrap; }
/* Under a stat that names it (the usage cards), the value read out sits over the chart's top right. */
.ds-barchart[data-bare] { position: relative; }
.ds-barchart[data-bare] > .ds-barchart-cap { position: absolute; top: -24px; right: 0; z-index: 1; height: auto; }
.ds-barchart[data-bare] .ds-chart-caption { display: none; }
.ds-barchart[data-bare] .ds-barchart-cap .ds-chart-meta { padding: 0 var(--ds-space-xs); background: var(--ds-color-surface); }
@media (prefers-reduced-motion: reduce) { .ds-bar { animation: none; } }
`

'use client'
import { useState, type PointerEvent } from 'react'
import { cn } from '@/lib/cn'

// Lines over time (LineChart.vue): one axis from 0, 2px lines in the brand's series order (red, neutral-400,
// neutral-600 dashed, so colour is never the only difference), the first series shading the area under it, a legend
// when there is more than one, and a crosshair with the values under the pointer. `smooth = k` draws each point as the
// mean of the points within k / 2 steps of it in time, for series too sparse to read point by point. In a card by
// default; `bare` drops the card, for a chart already inside one.
export type LineSeries = { label: string, points: Array<{ t: number, v: number }> }

export interface LineChartProps {
  title: string
  series: LineSeries[]
  format: (value: number) => string
  smooth?: number
  height?: number
  bare?: boolean
}

const W = 600
const H = 160
const COLORS = ['var(--ds-color-data-1)', 'var(--ds-color-data-2)', 'var(--ds-color-data-3)']
const DASH = ['', '', '5 4']

export function LineChart({ title, series, format, smooth, height, bare }: LineChartProps) {
  const all = [...new Set(series.flatMap(s => s.points.map(p => p.t)))].sort((a, b) => a - b)
  const step = Math.min(...all.slice(1).map((v, i) => v - all[i]!))
  function rolling(points: Array<{ t: number, v: number }>, k: number) {
    const reach = Math.floor(k / 2) * step
    if (!(reach > 0) || !Number.isFinite(reach)) return points
    return points.map((p) => {
      const near = points.filter(q => Math.abs(q.t - p.t) <= reach)
      return { t: p.t, v: near.reduce((n, q) => n + q.v, 0) / near.length }
    })
  }
  const lines = series.slice(0, 3).filter(s => s.points.length).map(s => ({ ...s, points: rolling(s.points, smooth ?? 1) }))
  const times = [...new Set(lines.flatMap(s => s.points.map(p => p.t)))].sort((a, b) => a - b)
  const span = { from: times[0] ?? 0, to: times[times.length - 1] ?? 1 }
  const top = Math.max(0, ...lines.flatMap(s => s.points.map(p => p.v)))
  const max = top <= 0 ? 1 : Math.ceil(top / 10 ** Math.floor(Math.log10(top))) * 10 ** Math.floor(Math.log10(top))
  const x = (t: number) => (span.to === span.from ? W / 2 : ((t - span.from) / (span.to - span.from)) * W)
  const y = (v: number) => H - (v / max) * H

  const paths = lines.map((s, i) => ({
    label: s.label,
    color: COLORS[i]!,
    dash: DASH[i]!,
    d: s.points.map((p, j) => `${j ? 'L' : 'M'}${x(p.t).toFixed(1)},${y(p.v).toFixed(1)}`).join(''),
    last: s.points[s.points.length - 1]!,
    area: i ? '' : `M${x(s.points[0]!.t).toFixed(1)},${H}${s.points.map(p => `L${x(p.t).toFixed(1)},${y(p.v).toFixed(1)}`).join('')}L${x(s.points[s.points.length - 1]!.t).toFixed(1)},${H}Z`,
  }))

  const [hover, setHover] = useState<number | null>(null)
  function move(event: PointerEvent<HTMLDivElement>) {
    const box = event.currentTarget.getBoundingClientRect()
    const t = span.from + ((event.clientX - box.left) / box.width) * (span.to - span.from)
    let best: number | null = null
    for (const c of times) if (best === null || Math.abs(c - t) < Math.abs(best - t)) best = c
    setHover(best)
  }
  // Local time; with the day too over a range longer than 12 hours.
  function clock(t: number) {
    const long = span.to - span.from > 12 * 3_600_000
    return new Date(t).toLocaleString('en-US', { ...(long ? { month: 'short', day: 'numeric' } : {}), hour: 'numeric', minute: '2-digit', hour12: false })
  }
  const hovered = hover === null
    ? null
    : {
        left: `${(x(hover) / W) * 100}%`,
        right: x(hover) > W * 0.6,
        time: clock(hover),
        values: lines.map((s, i) => ({ label: s.label, color: COLORS[i]!, value: s.points.find(p => p.t === hover)?.v })),
      }

  return (
    <figure data-ds="line-chart" className={cn(!bare && 'border border-edge bg-surface p-4')}>
      <figcaption className="mb-3 flex min-h-5 flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
        <span className="type-meta font-medium text-fg-muted">{title}</span>
        {lines.length > 1 && (
          <span className="flex flex-wrap gap-3 type-meta text-fg-muted">
            {paths.map(p => (
              <span key={p.label} className="inline-flex items-center gap-1">
                <svg width="16" height="4" aria-hidden="true"><line x1="0" y1="2" x2="16" y2="2" stroke={p.color} strokeWidth="2" strokeDasharray={p.dash} /></svg>
                {p.label}
              </span>
            ))}
          </span>
        )}
      </figcaption>
      {!lines.length
        ? <p className="type-ui text-fg-muted">No data in this range.</p>
        : (
            <div className="flex gap-2">
              <div className="relative h-40 w-14 shrink-0" aria-hidden="true">
                {[max, max / 2, 0].map((v, i) => <span key={i} className="type-meta text-fg-muted tabular-nums absolute right-0 -translate-y-1/2 whitespace-nowrap" style={{ top: `${i * 50}%` }}>{i === 2 ? '0' : format(v)}</span>)}
              </div>
              <div className="min-w-0 flex-1">
                <div
                  className="relative h-40 touch-none"
                  style={height ? { height: `${height}px` } : undefined}
                  role="img"
                  aria-label={`${title}: ${paths.map(p => `${p.label} last ${format(p.last.v)}`).join(', ')}`}
                  onPointerMove={move}
                  onPointerLeave={() => setHover(null)}
                >
                  <svg className="absolute inset-0 h-full w-full overflow-visible" viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none">
                    {[0, H / 2, H].map(g => <line key={g} x1="0" y1={g} x2={W} y2={g} stroke="var(--ds-color-data-grid)" strokeWidth="1" vectorEffect="non-scaling-stroke" />)}
                    {paths.filter(q => q.area).map(p => <path key={`${p.label}-area`} d={p.area} fill={p.color} fillOpacity="0.06" />)}
                    {paths.map(p => <path key={p.label} d={p.d} fill="none" stroke={p.color} strokeWidth="2" strokeDasharray={p.dash} strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />)}
                  </svg>
                  {hovered && (
                    <>
                      <div className="pointer-events-none absolute inset-y-0 w-px bg-ds-neutral-500" style={{ left: hovered.left }} />
                      <div
                        className="pointer-events-none absolute top-0 z-10 border border-edge bg-surface px-3 py-2 type-meta"
                        style={hovered.right ? { right: `calc(100% - ${hovered.left} + 8px)` } : { left: `calc(${hovered.left} + 8px)` }}
                      >
                        <p className="mb-1 text-fg-muted tabular-nums">{hovered.time}</p>
                        {hovered.values.map(v => (
                          <p key={v.label} className="flex items-center gap-2 whitespace-nowrap tabular-nums">
                            <span className="inline-block h-0.5 w-3" style={{ background: v.color }} />
                            {lines.length > 1 && <span className="text-fg-muted">{v.label}</span>}
                            <span className="font-medium">{v.value === undefined ? '–' : format(v.value)}</span>
                          </p>
                        ))}
                      </div>
                    </>
                  )}
                </div>
                <div className="type-meta text-fg-muted tabular-nums mt-2 flex justify-between">
                  <span>{clock(span.from)}</span>
                  <span>{clock(span.to)}</span>
                </div>
              </div>
            </div>
          )}
    </figure>
  )
}

export default LineChart

import { TrendArrow } from '@/components/ui/TrendArrow'

// The week's change on a usage card (usage/Trend.vue, take 1, the one picked): a second stat on the card's right, This
// week over the percent with the pixel triangle, red up and ink down. `change` is a share (0.12 is 12%).
export interface ChartTrendProps { change: number, label?: string }

export function ChartTrend({ change, label = 'This week' }: ChartTrendProps) {
  const down = change < 0
  const percent = `${Math.abs(Math.round(change * 100))}%`
  return (
    <div data-ds="chart-trend" className="shrink-0 text-right" title="The last 7 days against the 7 before">
      <p className="type-meta text-fg-muted">{label}</p>
      <p className="flex items-center justify-end gap-1.5 text-heading-4 font-medium tabular-nums"><TrendArrow down={down} bare /><span className="sr-only">{down ? 'down' : 'up'}</span>{percent}</p>
    </div>
  )
}

export default ChartTrend

import { cn } from '@/lib/cn'

// The way a number moved, in the website button's pixel arrow (usage/TrendArrow.vue): lit squares on a grid of dim
// ones, red going up, ink going down (turned over). `bare` is a solid pixel triangle with no grid, for beside a stat.
// It holds still: the branch's step on card hover is left out, since icons never move on hover.
export interface TrendArrowProps { down?: boolean, bare?: boolean }

const CELL = 3
const SIZE = 5
const GRID = Array.from({ length: SIZE * SIZE }, (_, k) => [k % SIZE, Math.floor(k / SIZE)] as const)
// [column, row] of the lit squares, pointing up.
const ARROW: Array<[number, number]> = [[2, 0], [1, 1], [2, 1], [3, 1], [0, 2], [2, 2], [4, 2], [2, 3], [2, 4]]
const TRIANGLE: Array<[number, number]> = [[2, 0], [1, 1], [2, 1], [3, 1], [0, 2], [1, 2], [2, 2], [3, 2], [4, 2]]

export function TrendArrow({ down, bare }: TrendArrowProps) {
  const rows = bare ? 3 : SIZE
  const ink = bare ? CELL : 2
  const wide = SIZE * CELL - (bare ? 0 : 1)
  const tall = rows * CELL - (bare ? 0 : 1)
  const lit = bare ? TRIANGLE : ARROW
  return (
    <svg data-ds="trend-arrow" className={cn('shrink-0 overflow-hidden', down && 'rotate-180')} width={wide} height={tall} viewBox={`0 0 ${wide} ${tall}`} aria-hidden="true">
      {!bare && <g className="fill-ds-neutral-700">{GRID.map(([x, y]) => <rect key={`${x}-${y}`} x={x * CELL} y={y * CELL} width="2" height="2" />)}</g>}
      <g className={down ? 'fill-fg' : 'fill-edge-accent'}>{lit.map(([x, y]) => <rect key={`${x}-${y}`} x={x * CELL} y={y * CELL} width={ink} height={ink} />)}</g>
    </svg>
  )
}

export default TrendArrow

'use client'
import { useLayoutEffect, useRef, useState } from 'react'
import { useControllable } from '@/hooks/useControllable'

// A whole in parts, as Billing's prices draw it (the chart's Split example): one bar, the parts in the order given
// (largest first), the picked part in ink with a red mark gliding over it; under it the parts as rows in a card, one
// paper block gliding to the row under the pointer or focus, and a red square on the picked row. Pointing at a row
// picks it (`value` / `defaultValue` / `onValueChange`, Vue's v-model). `detail` is a quiet middle column, hidden on
// phones; `display` is the value as written.
export type SplitPart = { name: string, value: number, display?: string, detail?: string }

export interface SplitBarProps {
  parts: SplitPart[]
  label?: string
  value?: number
  defaultValue?: number
  onValueChange?: (value: number) => void
}

export function SplitBar({ parts, label, value, defaultValue = 0, onValueChange }: SplitBarProps) {
  const [at, setAt] = useControllable(value, defaultValue, onValueChange)
  const total = parts.reduce((a, p) => a + p.value, 0) || 1
  // The parts share what the bar's 2px gaps leave, so those come out of the percent.
  const n = parts.length
  const i = Math.min(at, n - 1)
  const middle = (parts.slice(0, i).reduce((a, p) => a + p.value, 0) + (parts[i]?.value ?? 0) / 2) / total
  const center = `calc(${middle * 100}% + ${i * 2 - middle * 2 * (n - 1)}px)`

  // The gliding block: placed at once the first time, then it glides on transform.
  const list = useRef<HTMLUListElement | null>(null)
  const [mark, setMark] = useState<{ y: number, h: number } | null>(null)
  const [instant, setInstant] = useState(true)
  const had = useRef(false)
  function place(k: number) {
    const row = list.current?.querySelectorAll<HTMLElement>('[data-glide-row]')[k]
    if (!row) return
    setInstant(!had.current)
    had.current = true
    setMark({ y: row.offsetTop, h: row.offsetHeight })
  }
  function pick(k: number) {
    setAt(k)
    place(k)
  }
  useLayoutEffect(() => place(at), [at]) // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div data-ds="split-bar" className="flex flex-col gap-4">
      <style href="ds-split-bar" precedence="ds">{css}</style>
      <div className="ds-segmark-track" aria-hidden="true"><span className="ds-segmark" style={{ transform: `translateX(${center})` }}><i /></span></div>
      <div className="ds-splitbar" aria-hidden="true">
        {parts.map((p, k) => <span key={p.name} data-on={at === k || undefined} style={{ flexGrow: p.value / total }} />)}
      </div>
      <ul ref={list} className="relative border border-edge bg-surface" aria-label={label}>
        {mark && <span className="ds-rowmark" data-instant={instant || undefined} style={{ transform: `translateY(${mark.y}px)`, height: `${mark.h}px` }} aria-hidden="true" />}
        {parts.map((p, k) => (
          <li key={p.name} data-glide-row="" className="border-edge [&+&]:border-t">
            <button type="button" className="ds-priced" data-on={at === k || undefined} aria-pressed={at === k} onPointerEnter={() => pick(k)} onFocus={() => pick(k)} onClick={() => pick(k)}>
              <span className="min-w-0 flex-1 truncate text-left">{p.name}</span>
              {p.detail && <span className="hidden text-fg-muted tabular-nums sm:inline">{p.detail}</span>}
              <span className="w-24 text-right tabular-nums">{p.display ?? p.value.toLocaleString('en-US')}</span>
            </button>
          </li>
        ))}
      </ul>
    </div>
  )
}

export default SplitBar

const css = `
/* console2.css .v2-splitbar, .v2-segmark, .v2-rowmark and .v2-priced, as Billing's prices set them (data-pm="6"). */
.ds-splitbar { display: flex; height: 12px; gap: var(--ds-space-2xs); margin-top: var(--ds-space-xs); }
.ds-splitbar > span { flex-basis: 0; background: var(--ds-color-neutral-600); transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-splitbar > span[data-on] { background: var(--ds-color-surface-inverse); }
.ds-segmark-track { position: relative; height: 8px; margin-bottom: -12px; overflow: clip; }
.ds-segmark { position: absolute; inset: 0; transition: transform var(--ds-duration-settle) var(--ds-easing-out); }
.ds-segmark i { position: absolute; top: 0; left: -3px; width: 6px; height: 6px; background: var(--ds-color-edge-accent); }
.ds-rowmark { position: absolute; top: 0; right: 0; left: 0; z-index: 0; background: var(--ds-color-surface-subtle); pointer-events: none; transition: transform var(--ds-duration-enter) var(--ds-easing-out), height var(--ds-duration-enter) var(--ds-easing-out); }
.ds-rowmark[data-instant] { transition: none; }
.ds-priced { position: relative; z-index: 1; display: flex; width: 100%; min-height: var(--ds-size-row); align-items: center; gap: var(--ds-space-xl); padding: 0 16px 0 20px; font-size: var(--ds-text-ui); cursor: pointer; }
.ds-priced::before { position: absolute; top: 50%; left: 8px; width: 4px; height: 4px; margin-top: -2px; background: var(--ds-color-edge-accent); content: ""; opacity: 0; transition: opacity var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-priced[data-on]::before { opacity: 1; }
.ds-priced:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent); outline-offset: -2px; }
@media (prefers-reduced-motion: reduce) { .ds-splitbar > span, .ds-segmark, .ds-rowmark { transition: none; } }
`

// What the charts share (usageMetrics.ts, BarChart.vue): numbers in en-US, an axis that ends on a round number in four
// steps, and the week's change.

export type DayPoint = { day: string, value: number }
export type ChartMetric = { key: string, label: string, points: DayPoint[] }

const whole = new Intl.NumberFormat('en-US')
const compact = new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 })

/** 186402 -> "186,402". */
export const formatNumber = (n: number) => whole.format(n)
/** 186402 -> "186.4K", for axis labels. */
export const compactNumber = (n: number) => compact.format(n)

/** The axis: a step of 1, 2, 2.5 or 5 times a power of ten that covers the largest value in four. Starts at 0. */
export function niceTicks(values: number[]) {
  const max = Math.max(0, ...values)
  if (max === 0) return [0, 1]
  const raw = max / 4
  const power = 10 ** Math.floor(Math.log10(raw))
  const step = ([1, 2, 2.5, 5, 10].find(m => m * power >= raw) ?? 10) * power
  return Array.from({ length: Math.ceil(max / step) + 1 }, (_, i) => i * step)
}

/** "Oct 2", or "Oct 2, 2026" with the year, from an ISO day. */
export const formatDay = (value: string, year = false) => new Date(`${value}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', ...(year ? { year: 'numeric' } : {}), timeZone: 'UTC' })

/** The sum of a metric's points over its range. */
export const totalOf = (points: DayPoint[]) => points.reduce((a, p) => a + p.value, 0)

/** The last seven days against the seven before, as a share; null without both. */
export function weekChange(points: DayPoint[]): number | null {
  if (points.length < 14) return null
  const before = totalOf(points.slice(-14, -7))
  return before ? (totalOf(points.slice(-7)) - before) / before : null
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

'use client'
import { useCallback, useRef, useState } from 'react'

// Vue's defineModel in React: a value that is controlled when the caller passes it (value + onValueChange, as Radix
// does) and kept inside otherwise (defaultValue). setValue calls onChange either way.
export function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (value: T) => void) {
	const [inner, setInner] = useState<T>(defaultValue)
	const controlled = value !== undefined
	const current = controlled ? value : inner
	const ref = useRef(onChange)
	ref.current = onChange
	const set = useCallback((next: T) => {
		if (!controlled) setInner(next)
		ref.current?.(next)
	}, [controlled])
	return [current, set] as const
}
